"""Authored relationship arcs. Every choice is durable; promises refer to playable activities."""
from pathlib import Path
import json

def choice(label,text,flag,promise='',affinity=3,trust=4):return dict(label=label,text=text,flag=flag,promise=promise,affinity=affinity,trust=trust)
def chapter(title,text,a,b):return dict(title=title,text=text,choices=[a,b])
def activity(id,label,minutes,cost,text):return dict(id=id,label=label,minutes=minutes,cost=cost,text=text)
